WITH valid AS (SELECT id, product_name, category, brand, price, cost, stock_qty, launch_date, supplier_id, DATE_FORMAT(launch_date, 'yyyy-MM-dd') AS launch_date_label, COALESCE(brand, 'UNKNOWN') AS resolved_brand FROM products WHERE price BETWEEN 690 AND 760) SELECT s.* FROM valid s WHERE NOT EXISTS (SELECT 1 FROM store_sales ch WHERE ch.product_id = s.id AND ch.sale_date >= s.launch_date);
